<?php
require_once __DIR__ . '/../app/bootstrap.php';
require_auth();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$id){http_response_code(404);exit('Lead not found');}
$statusLabels=['new'=>'New','contacted'=>'Contacted','qualified'=>'Qualified','proposal'=>'Proposal','won'=>'Won','lost'=>'Lost'];
$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 if($action==='activity'){
  $body=trim($_POST['description']??'');$type=$_POST['type']??'note';$allowed=['note','call','email','whatsapp','meeting','task'];
  if($body!==''&&in_array($type,$allowed,true))$pdo->prepare('INSERT INTO activities (lead_id,user_id,type,description) VALUES (?,?,?,?)')->execute([$id,$_SESSION['user_id'],$type,$body]);
 }elseif($action==='status'){
  $status=$_POST['status']??'';if(array_key_exists($status,$statusLabels)){$pdo->prepare('UPDATE leads SET status=? WHERE id=?')->execute([$status,$id]);$pdo->prepare("INSERT INTO activities (lead_id,user_id,type,description) VALUES (?,?, 'note', ?)")->execute([$id,$_SESSION['user_id'],'Status changed to '.$statusLabels[$status]]);}
 }
 header('Location: lead-view.php?id='.$id);exit;
}
$stmt=$pdo->prepare('SELECT * FROM leads WHERE id=? LIMIT 1');$stmt->execute([$id]);$lead=$stmt->fetch();if(!$lead){http_response_code(404);exit('Lead not found');}
$stmt=$pdo->prepare('SELECT a.*,u.name AS user_name FROM activities a LEFT JOIN users u ON u.id=a.user_id WHERE a.lead_id=? ORDER BY a.created_at DESC');$stmt->execute([$id]);$activities=$stmt->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($lead['name'])?> | AI CRM</title><link rel="stylesheet" href="assets/app.css"></head><body><header class="topbar"><div class="brand">AI CRM</div><nav><a href="index.php">Dashboard</a><a href="leads.php">Leads</a><a href="pipeline.php">Pipeline</a><a href="tasks.php">Tasks</a><a href="analytics.php">Analytics</a><a href="logout.php">Logout</a></nav></header><main class="container"><div class="page-head"><div><p class="eyebrow">LEAD</p><h1><?=e($lead['name'])?></h1><p class="muted"><?=e($lead['company'])?> · <?=e($lead['email'])?></p></div><div class="head-actions"><a class="btn" href="lead-edit.php?id=<?=$id?>">Edit lead</a><a class="btn primary" href="ai-assistant.php?id=<?=$id?>">✨ AI Analyze</a><a class="btn" href="leads.php">← Back</a></div></div><section class="stats"><article><span>Status</span><strong><?=e($statusLabels[$lead['status']]??ucfirst($lead['status']))?></strong></article><article><span>AI score</span><strong><?= $lead['ai_score']!==null?(int)$lead['ai_score'].'/100':'Pending' ?></strong><a href="ai-score.php?id=<?=$id?>" class="small">Run score</a></article><article><span>Value</span><strong>₹<?=number_format((float)$lead['value'],0)?></strong></article><article><span>Follow-up</span><strong class="small"><?= $lead['follow_up_at']?e(date('d M Y, h:i A',strtotime($lead['follow_up_at']))):'Not set' ?></strong></article></section><div class="form-grid"><section class="panel"><div class="panel-head"><h2>Lead details</h2></div><p><b>Phone:</b> <?=e($lead['phone'])?:'—'?></p><p><b>Source:</b> <?=e($lead['source'])?:'—'?></p><p><b>Status:</b> <?=e(ucfirst($lead['status']))?></p><p><b>Notes:</b><br><?=nl2br(e($lead['notes']))?:'—'?></p><form method="post" style="margin-top:20px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><label>Update status<select name="status"><?php foreach($statusLabels as $key=>$label):?><option value="<?=e($key)?>" <?=$key===$lead['status']?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><button class="btn primary" style="margin-top:12px" type="submit">Update status</button></form></section><section class="panel"><div class="panel-head"><h2>Add activity</h2></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="activity"><label>Type<select name="type"><option>note</option><option>call</option><option>email</option><option>whatsapp</option><option>meeting</option><option>task</option></select></label><label style="margin-top:14px">Note / activity<textarea name="description" rows="5" required></textarea></label><button class="btn primary" style="margin-top:12px" type="submit">Add activity</button></form></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h2>Activity timeline</h2></div><?php if(!$activities):?><p class="muted">No activity yet.</p><?php endif;?><?php foreach($activities as $a):?><div style="padding:14px 0;border-bottom:1px solid #edf0f5"><b><?=e(ucfirst($a['type']))?></b> <span class="muted small">· <?=e($a['user_name']??'System')?> · <?=e(date('d M Y, h:i A',strtotime($a['created_at'])))?></span><p><?=nl2br(e($a['description']))?></p></div><?php endforeach;?></section></main></body></html>
